 }catch{
  await admin.from('shipment_tracking_runs').update({completed_at:new Date().toISOString(),claimed,succeeded,failed,error:'TRACKING_WORKER_FAILED'}).eq('id',run);
  throw Error('TRACKING_WORKER_FAILED');
 }
}
